head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25910";
scwin.ex = null;
scwin.filebox = null;
scwin.modifiyDate = "N";
scwin.delck = "N";
scwin.upd_attachFile = null;
scwin.result = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.ex = $c.util.getComponent('ex');
        scwin.filebox = $c.util.getComponent('filebox');
        scwin.upd_attachFile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile"]');
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25910.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("sysYear")) { pc.set("sysYear", $c.date.getServerDateTime("yyyy")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — checkModifiyDate, listStatCd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_shrhdNmlistClsBasddContn", attr: "label", fn: function () { return String(dma_dividendDate.get("shrhdNmlistClsBasddContn")); } },
        { childId: "txa_proftDivRemk", attr: "label", fn: function () { return String(dma_dividendDate.get("proftDivRemk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_attachFileNm", fn: function(){ return (!(String(((dma_dividendDate.get("attachFileNm") ?? (() => { throw new Error("unresolved:" + "dividendDate.attachFileNm"); })())) == null ? '' : ((dma_dividendDate.get("attachFileNm") ?? (() => { throw new Error("unresolved:" + "dividendDate.attachFileNm"); })()))).length === 0)); } }, { id: "if_checkModifiyDate", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y'); } }, { id: "tr_63", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y'); } }, { id: "tr_70", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y'); } }, { id: "tr_73", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y'); } }, { id: "tr_78", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y'); } }, { id: "tr_83", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y'); } }, { id: "if_checkModifiyDate_2", fn: function(){ return ((dma_pageContext.get("checkModifiyDate") ?? "") === 'N' || (dma_pageContext.get("listStatCd") ?? "") !== 'Y'); } }, { id: "tr_98", fn: function(){ return ((dma_pageContext.get("checkModifiyDate") ?? "") === 'N' || (dma_pageContext.get("listStatCd") ?? "") !== 'Y'); } }, { id: "tr_105", fn: function(){ return ((dma_pageContext.get("checkModifiyDate") ?? "") === 'N' || (dma_pageContext.get("listStatCd") ?? "") !== 'Y'); } }, { id: "tr_108", fn: function(){ return ((dma_pageContext.get("checkModifiyDate") ?? "") === 'N' || (dma_pageContext.get("listStatCd") ?? "") !== 'Y'); } }, { id: "tr_112", fn: function(){ return ((dma_pageContext.get("checkModifiyDate") ?? "") === 'N' || (dma_pageContext.get("listStatCd") ?? "") !== 'Y'); } }, { id: "tr_116", fn: function(){ return ((dma_pageContext.get("checkModifiyDate") ?? "") === 'N' || (dma_pageContext.get("listStatCd") ?? "") !== 'Y'); } }, { id: "registerBtn", fn: function(){ return ((String(((dma_dividendDate.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "dividendDate.bzProcsNo"); })())) == null ? '' : ((dma_dividendDate.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "dividendDate.bzProcsNo"); })()))).length === 0)); } }, { id: "registerBtn_2", fn: function(){ return (!(String(((dma_dividendDate.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "dividendDate.bzProcsNo"); })())) == null ? '' : ((dma_dividendDate.get("bzProcsNo") ?? (() => { throw new Error("unresolved:" + "dividendDate.bzProcsNo"); })()))).length === 0)); } }, { id: "registerBtn", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y' && (dma_dividendDate.get("basYy") ?? (() => { throw new Error("unresolved:" + "dividendDate.basYy"); })()) === (() => { throw new Error("unresolved:data:" + "sysYear.toString"); })()()); } }, { id: "registerBtn_2", fn: function(){ return (((dma_pageContext.get("checkModifiyDate") ?? "") === 'Y' ||(dma_pageContext.get("checkModifiyDate") ?? "") === 'U') && (dma_pageContext.get("listStatCd") ?? "") === 'Y' && (dma_dividendDate.get("basYy") ?? (() => { throw new Error("unresolved:" + "dividendDate.basYy"); })()) === (() => { throw new Error("unresolved:data:" + "sysYear.toString"); })()()); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(dma_dividendDate.get("basYy")) + " 년"; } },
        { childId: "__rb3", fn: function () { return String(dma_dividendDate.get("acntclsMm")) + " 월"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.basDRadio();
        // TODO Stage2(규칙 19): jQuery — 스크립트 바인딩 → 컴포넌트 ev:on* 속성 + scwin 핸들러(규칙 3)
        $("input[name='divBasDdYn']").change(function() {
                const yn = this.value;
                if (yn === "Y") {
                    $c.util.getComponent('cal_divBasDd').setValue("");
                    // TODO Stage2(규칙 19): jQuery — 스크립트 바인딩 → 컴포넌트 ev:on* 속성 + scwin 핸들러(규칙 3)
                    $(".ui-datepicker-trigger").click();
                    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                } else {
                    $c.util.getComponent('cal_divBasDd').setValue("-");
                    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25910.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

