/**
 * @method
 * @name fileValidation
 * @description file Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileValidation = async function () {
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const file = $("input[type='file']");
    if (file.attr("value") !== '' && file.attr("value") != null) {
        if (scwin.fileTypeChk(file.attr("value")) > 0) {
            await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + '있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
            return false;
        }
        if (scwin.fileSizeChk($c.util.getComponent("upd_attachFile").files[0].size) > 0) {
            await $c.win.alert('첨부파일의 용량은 개당 20MB를 넘을수 없습니다.');
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name fileTypeChk
 * @description file Type Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fileTypeChk = function (val) {
    const isFileType = ["drt", "bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt"];
    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt === 0) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fileSizeChk
 * @description file Size Chk 처리
 * @param {*} fileSize fileSize
 * @returns {void}
 * @hidden N
 */
scwin.fileSizeChk = function (fileSize) {
    if (fileSize > (1024 * 1024 * 20)) {
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validation = async function () {
    if (scwin.modifiyDate === "N") {
        await $c.win.alert("제출 시간을 초과했습니다.");
        return false;
    }
    if (($c.util.getComponent('cal_divBasDd').getValue() == null ? '' : String($c.util.getComponent('cal_divBasDd').getValue())) === '') {
        await $c.win.alert("배당기준일을 등록해주세요.");
        return false;
    }
    if (($c.util.getComponent('txa_shrhdNmlistClsBasddContn').getValue() == null ? '' : String($c.util.getComponent('txa_shrhdNmlistClsBasddContn').getValue())) === '') {
        await $c.win.alert("주주명부의 폐쇄 및 기준일을 등록해주세요.");
        return false;
    }
    if (($c.util.getComponent('txa_proftDivRemk').getValue() == null ? '' : String($c.util.getComponent('txa_proftDivRemk').getValue())) === '') {
        await $c.win.alert("이익배당을 등록해주세요.");
        return false;
    }
    if (($c.util.getComponent('upd_attachFile').getValue() == null ? '' : String($c.util.getComponent('upd_attachFile').getValue())) === '') {
        if (($c.util.getComponent('ipt_bzProcsNo').getValue() == null ? '' : String($c.util.getComponent('ipt_bzProcsNo').getValue())) === '') {
            await $c.win.alert("첨부파일을 등록해주세요.");
            return false;
        } else {
            if (scwin.delck === "Y") {
                await $c.win.alert("첨부파일을 등록해주세요.");
                return false;
            }
        }
    }
    if (!await scwin.fileValidation()) {
        return false;
    }
    return true;
};

