 */
scwin.modifiyDateDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    scwin.modifiyDate = scwin.result.checkModifiyDate;
};

/**
 * @method
 * @name selectModifiyDate
 * @description select Modifiy Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectModifiyDate = async function () {
    const r = await scwin.tx_fn_modifiyDate();
    try {
        scwin.modifiyDateDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil25910.fn_modifiyDate' });
    }
    return r;
};
